  "claims": [
    {
      "claim": "All transferable L1 gold records report absolute or systemic oral bioavailability at or above 20%: ranitidine 54±22% and 58±11% in cirrhosis; didanosine 26±5%, 35±5%, and 29±6%; nitecapone 38–59%; thalidomide probably high/80–100%; tegafur almost 100%; chloramphenicol excellent or >100% in children; (R)- and (S)-thalidomide around 80–100%.",
      "card_ids": ["C08","C09","C13","C20","C12","C14","C06","C18","C01","C03","C10","C19","C02","C16","C04","C07","C11","C17"]
    },
    {
      "claim": "L2 context records reinforce the high-F direction (ranitidine 70% and 70±7% in cirrhosis; tegafur 43.79±7.80% in dogs; chloramphenicol equivalent oral/IV AUC and 78.1% relative F in horses; thalidomide high/orally bioavailable). Didanosine variability (2–89%) and average <40% do not affirm F<20%.",
      "card_ids": ["C21","C22","C23","C24","C25","C27","C29","C30","C26","C28"]
    },
    {
      "claim": "L3 oral exposure records for nitroheterocycles and related drugs show measurable oral Cmax/AUC, but none includes an IV comparator or F value, so they neither establish nor refute the F≥20% threshold for the query.",
      "card_ids": ["C31","C32","C33","C34","C35","C36","C37","C38","C39","C40","C41","C42"]
    },
    {
      "claim": "L4 in vivo absorption records for close nitrofuran/hydantoin analogs show high fraction absorbed: dantrolene ~80% in normal subjects (C49) and high absorption in rats irrespective of gastric pH (C50); nitrofurazone 88% absorbed in rats (C47, C51); furazolidone minimum ~75% absorption in rats (C45). These support the absorption component for the query, which shares the nitrofuran hydantoin semicarbazone core.",
      "card_ids": ["C49","C50","C47","C51","C45"]
    },
    {
      "claim": "Additional L4 records show that nitro-containing and/or poorly soluble drugs can be well absorbed (clonazepam complete absorption, CGP 6140 well absorbed, nifedipine complete absorption/BCS class 1), so the low passive-permeability physicochemical prior is not affirmative evidence of F<20%. Solubility records (C48, C53) are formulation/salt-specific and do not contradict the absorption evidence.",
      "card_ids": ["C43","C44","C46","C52","C54","C48","C53"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C43","C44","C45","C46","C47","C49","C50","C51","C52","C54"]
    }
  ],
  "evidence_gaps": [
    "No direct nitrofurantoin-specific absolute oral bioavailability record is supplied.",
    "No matched oral-versus-IV AUC data for the query molecule are available.",
    "L4 fraction-absorbed data are from close analogs (dantrolene, nitrofurazone, furazolidone), not from the query itself.",
    "First-pass metabolism and systemic clearance for the query are not quantified.",
    "No direct permeability or efflux assay for the query is provided."
  ],
  "decision_summary": "Predicted high (F>=20%) because all transferable gold records are at or above 20%, L4 in vivo absorption data for close nitrofuran/hydantoin analogs show high fraction absorbed, and no affirmative threshold-relevant evidence supports F<20%; confidence strengthened to high."
}

